files.infra/nginx-edge-upstream.conf:
# edge upstream pool for the invoice service
upstream invoice_pool {
    least_conn;
    server 10.20.4.11:9100 max_fails=2;
    server 10.20.4.12:9100 max_fails=2;
    server 10.20.4.13:9100 backup;
    keepalive 32;
}

server {
    listen 443 ssl;
    server_name invoice.northgate.internal;
    location / {
        proxy_pass http://invoice_pool;
    }
}

